    "id": "cetus",
    "chain": "sui-mainnet"
  },
  "scope": {
    "business": "Cetus已选haSUI/SUI Farm的三币池级奖励会计",
    "selection": "仅按已知ID读取同一具名池的3条奖励汇总记录；不枚举池、不读用户、不查交易。"
  },
  "semantics": {
    "result": "直接记录链上事实。缺少的权限证明、资金汇总和评分规则按具体业务单列。",
